#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с приборомtypedef struct : public Queue_PRS  {  CShValue   sh;  } Queue_Control;////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintControl(DefinePaint)  {  QueueP(Queue_Control);  if ( !p->m_bPressed )    {    CShBase* sh = PipeSh;    if ( IsTypeOk )      memcpy( &p->sh, sh, sizeof(p->sh) );    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~static void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_Control* p = (Queue_Control*)base;  CShBase* sh = p->pPipe->Sh(p->nNumber);  if ( !IsTypeOk ) return;  //  p->send.SetNew( pVoid );  p->pPipe->SendData( p->send, bMessage );  p->m_bPressed = !bMessage;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void FillControl( SPriborBase* d, void* pp )  {  d->fnData = fnSendData;  Queue_Control* p = (Queue_Control*)pp;  d->pVoid = &p->sh.dVal;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddControl(DefineTegs)  {  char* parm = strrchr( teg[0].value, '.' );  ASSERT( parm != NULL );  if ( parm == NULL ) return;  //  AddQueueEx(Queue_Control);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintControl;  // Строим имя объекта и параметра  CharMP szObj;  *parm++ = 0;  lstrcpy( szObj, def.Pipe()->ActObj() );  lstrcat( szObj, teg[0].value );  teg[0].value = parm;  //  p->nNumber = def.AddKindEx( id_Value, szObj );  //  CShValue sh;  memcpy( &p->sh, &sh, sizeof(p->sh) );  p->pSH = &p->sh;  //  HPRIBOR hPribor = AddPribors( def, teg, Buffer, p, &FillControl, id_Value );  if ( hPribor == NULL )    {    Buffer.nPtr -= sizeof(Queue_Control);    memset( Buffer.szQueue+Buffer.nPtr, 0, sizeof(Queue_Control) );    }  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~